from taf.sbts.oam.coam.admin.utils import raise_value_error


class AccountMgmtInterface21B(object):
    def change_local_account_state(self, account_type, enable, timeout=60):
        """
        Change local account state.

        :param string account_type: BtsSecurity, BtsApplication or BtsRead
        :param boolean enable: Should enable.
        :param int timeout: Time to wait for positive procedure result.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-changeLocalAccountState.html
        """
        if account_type not in ("BtsSecurity", "BtsApplication", "BtsRead"):
            raise_value_error(param="account_type",
                              value=str(account_type),
                              subpage="tutorial-changeLocalAccountState.html")
        self._api_client.execute_procedure("changeLocalAccountState", {"accountType": account_type, "enable": enable},
                                           timeout)

    def change_ssh_password(self, username, new_password, old_password, timeout=60):
        """
        Change SSH password.

        :param string username: Username.
        :param string new_password: New password.
        :param string old_password: Old password.
        :param int timeout: Time to wait for positive procedure result.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-modifySshUser.html
        """

        parameters = {
            "username": username,
            "password": new_password,
            "oldUsername": username,
            "oldPassword": old_password,
        }
        self._api_client.execute_procedure("modifySshUser", parameters, timeout)

    def set_user_account(self, old_username, old_password, new_username=None, new_password=None, delete_flag=False,
                         timeout=60):
        """
        Set user account.

        :param string old_username: Old username.
        :param string old_password: Old password.
        :param string new_username: New username.
        :param string new_password: New password.
        :param bool delete_flag: Delete flag.
        :param int timeout: Time to wait for positive procedure result.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-userAccountSet.html
        """

        parameters = {
            "oldUsername": old_username,
            "oldPassword": old_password
        }

        if new_username:
            parameters["username"] = new_username

        if new_password:
            parameters["password"] = new_password

        if delete_flag:
            parameters["deleteFlag"] = delete_flag

        self._api_client.execute_procedure("userAccountSet", parameters, timeout)

    def get_user_login_info(self, timeout=60):
        """
        Get user login info.

        :param int timeout: Time to wait for positive procedure result.
        :return dict: massage of login info objects.

        More details (content of requestMessage is returned data):
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getUserLoginInfo.html
        """

        return self._api_client.execute_infomodel_request("getUserLoginInfo", {}, timeout)

    def modify_web_service_user(self, username, password, old_username, old_password, timeout=60):
        """
        Modify web service user.

        :param str username: New username.
        :param str password: New password.
        :param str old_username: Old username.
        :param str old_password: Old password.
        :param int timeout: Time to wait for positive procedure result.

        :return str: Status of the operation.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-modifyWebServiceUser.html
        """

        parameters = {
            "username": username,
            "password": password,
            "oldUsername": old_username,
            "oldPassword": old_password}

        return self._api_client.execute_procedure("modifyWebServiceUser", parameters, timeout)
